// Classical multidimensional scaling (Torgerson-Gower) with the Cailliez additive constant.
import { eigen } from "../linalg/eigen.js";
import type { DistResult } from "./dist.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const CMDSCALE_KEYS = ["k", "add", "xRet"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** @category Multivariate analysis */
export interface CmdscaleOptions {
  /** Number of coordinate dimensions to retain. */
  k?: number;
  /** Whether to add the Cailliez constant to make the dissimilarities Euclidean. */
  add?: boolean;
  /** Whether to return the double-centered squared-distance matrix. */
  xRet?: boolean;
}
/** @category Multivariate analysis */
export interface CmdscaleInputTable {
  /** Observation labels, or null when labels are unavailable. */
  rows: string[] | null;
  /** Coordinate labels, or null for an unlabeled coordinate matrix. */
  cols: string[] | null;
  /** Numeric matrix values arranged by row. */
  values: number[][];
}
/** @category Multivariate analysis */
export interface CmdscaleResult {
  /** Principal coordinate matrix for the retained positive eigenvalues. */
  points: CmdscaleInputTable;
  /** All eigenvalues of the double-centered Gram matrix, including negative values. */
  eig: number[];
  /** Double-centered squared-distance matrix when xRet is true; otherwise null. */
  x: CmdscaleInputTable | null;
  /** Cailliez additive constant, or zero when add is false. */
  ac: number;
  /** Goodness of fit relative to the absolute-eigenvalue sum and positive-eigenvalue sum. */
  GOF: [number, number];
  /** Warnings such as a request for more positive dimensions than are available. */
  warnings: string[];
}

interface DistanceInput { matrix: number[][]; labels: string[] | null; }

function readDistances(input: DistResult | readonly (readonly number[])[] | CmdscaleInputTable): DistanceInput {
  if (Array.isArray(input)) {
    const n = input.length;
    if (n === 0 || input.some((r) => r.length !== n)) throw new RangeError("distance matrix must be square");
    const matrix = input.map((r) => Array.from(r, Number));
    if (matrix.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("NA values not allowed in 'd'");
    return { matrix, labels: null };
  }
  if (typeof input !== "object" || input === null || !Array.isArray((input as DistResult).values)) {
    throw new TypeError("d must be a dist object or a square matrix");
  }
  const rawValues = (input as { values: unknown[] }).values;
  if (rawValues.length > 0 && Array.isArray(rawValues[0])) {
    const table = input as CmdscaleInputTable;
    const n = table.values.length;
    if (n === 0 || table.values.some((r) => r.length !== n)) throw new RangeError("distance matrix must be square");
    const matrix = table.values.map((r) => Array.from(r, Number));
    if (matrix.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("NA values not allowed in 'd'");
    return { matrix, labels: table.rows === null ? null : [...table.rows] };
  }
  const d = input as DistResult;
  const n = d.size;
  if (!Number.isInteger(n) || n < 1 || d.values.length !== n * (n - 1) / 2) throw new RangeError("invalid dissimilarity object");
  if (d.values.some((v) => !Number.isFinite(v))) throw new RangeError("NA values not allowed in 'd'");
  const matrix = Array.from({ length: n }, () => new Array<number>(n).fill(0));
  let p = 0;
  for (let j = 0; j < n - 1; j++) for (let i = j + 1; i < n; i++) {
    matrix[i]![j] = d.values[p]!;
    matrix[j]![i] = d.values[p]!;
    p++;
  }
  return { matrix, labels: d.labels === null ? null : [...d.labels] };
}

function centerMatrix(d: readonly (readonly number[])[]): number[][] {
  const n = d.length;
  const rowMeans = new Array<number>(n).fill(0);
  const colMeans = new Array<number>(n).fill(0);
  let grand = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    rowMeans[i] = rowMeans[i]! + d[i]![j]!;
    colMeans[j] = colMeans[j]! + d[i]![j]!;
  }
  for (let i = 0; i < n; i++) { rowMeans[i] = rowMeans[i]! / n; colMeans[i] = colMeans[i]! / n; grand += rowMeans[i]!; }
  grand /= n;
  return d.map((row, i) => row.map((v, j) => v - rowMeans[i]! - colMeans[j]! + grand));
}

function gramFromDistances(d: readonly (readonly number[])[]): { x: number[][]; gram: number[][] } {
  const squared = d.map((row) => row.map((v) => v * v));
  const x = centerMatrix(squared);
  const n = d.length;
  const gram = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) =>
    i >= j ? -x[i]![j]! / 2 : -x[j]![i]! / 2));
  return { x, gram };
}

function cailliez(d: readonly (readonly number[])[]): number {
  const n = d.length;
  let scale = 0;
  for (const row of d) for (const value of row) scale = Math.max(scale, Math.abs(value));
  const rescale = scale > 2 ** 450 || (scale > 0 && scale < 2 ** -450);
  const work = rescale ? d.map((row) => row.map((value) => value / scale)) : d;
  const multiplier = rescale ? scale : 1;
  // Cailliez (1983): c is the largest real eigenvalue of
  // [[0, 2 B0], [-I, -4 B1]], with B0/B1 the double-centered D^2/D
  // matrices multiplied by -1/2.
  const B0 = centerMatrix(work.map((row) => row.map((v) => v * v))).map((row) => row.map((v) => -v / 2));
  const B1 = centerMatrix(work).map((row) => row.map((v) => -v / 2));
  const size = 2 * n;
  const companion = Array.from({ length: size }, () => new Array<number>(size).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      companion[i]![n + j] = 2 * B0[i]![j]!;
      companion[n + i]![n + j] = -4 * B1[i]![j]!;
    }
    companion[n + i]![i] = -1;
  }
  const values = eigen(companion, { symmetric: false, onlyValues: true });
  let largest = 0;
  for (let i = 0; i < values.values.length; i++) {
    const real = values.values[i]!;
    const imaginary = values.valuesIm?.[i] ?? 0;
    if (Math.abs(imaginary) <= 1e-10 * Math.max(1, Math.abs(real)) && real > largest) largest = real;
  }
  return largest * multiplier;
}
function orient(points: number[][]): void {
  if (points.length === 0) return;
  const k = points[0]!.length;
  for (let j = 0; j < k; j++) {
    let at = 0, largest = -1;
    for (let i = 0; i < points.length; i++) {
      const value = Math.abs(points[i]![j]!);
      if (value > largest) { largest = value; at = i; }
    }
    if (points[at]![j]! < 0) for (let i = 0; i < points.length; i++) points[i]![j] = -points[i]![j]!;
  }
}

/**
 * Classical (metric) multidimensional scaling of a dissimilarity structure.
 * Equivalent to R's `cmdscale()`.
 * @category Multivariate analysis
 */
export function cmdscale(
  input: DistResult | readonly (readonly number[])[] | CmdscaleInputTable,
  options: CmdscaleOptions = {},
): CmdscaleResult {
  checkOptions(options, CMDSCALE_KEYS, "cmdscale"); // generated: option-keys.mjs
  const parsed = readDistances(input);
  const n = parsed.matrix.length;
  if (n < 2) throw new RangeError("'k' must be in {1, 2, ..  n - 1}");
  const k = options.k ?? 2;
  if (!Number.isFinite(k) || !Number.isInteger(k) || k < 1 || k >= n) {
    throw new RangeError(`'k' must be in {1, 2, ..  ${n - 1}}`);
  }
  // Squaring extreme dissimilarities can erase their Gram matrix even when the coordinates
  // themselves are representable. Normalize only outside the safe square range; ordinary inputs
  // retain the original operation order and bit patterns.
  let magnitude = 0;
  for (const row of parsed.matrix) for (const value of row) magnitude = Math.max(magnitude, Math.abs(value));
  const rescale = magnitude > 2 ** 512 || (magnitude > 0 && magnitude < 2 ** -512);
  const workMatrix = rescale ? parsed.matrix.map((row) => row.map((value) => value / magnitude)) : parsed.matrix;
  const acWork = options.add ? cailliez(workMatrix) : 0;
  const adjusted = workMatrix.map((row, i) => row.map((v, j) => i === j ? v : v + acWork));
  const centered = gramFromDistances(adjusted);
  const decomposition = eigen(centered.gram, { symmetric: true });
  const positive = decomposition.values.filter((v) => v > 0);
  const dimensions = Math.min(k, positive.length);
  const vectors = decomposition.vectors!;
  const points = Array.from({ length: n }, (_, i) => Array.from({ length: dimensions }, (_, j) => {
    const coordinate = vectors[i]![j]! * Math.sqrt(positive[j]!);
    return rescale ? coordinate * magnitude : coordinate;
  }));
  orient(points);
  const absSum = decomposition.values.reduce((s, v) => s + Math.abs(v), 0);
  const positiveSum = positive.reduce((s, v) => s + v, 0);
  const retained = positive.slice(0, dimensions).reduce((s, v) => s + v, 0);
  const warnings = dimensions < k ? [`only ${dimensions} of the first ${k} eigenvalues are > 0`] : [];
  const restoreSquare = (value: number): number => value === 0 ? 0 : (value * magnitude) * magnitude;
  const eigenvalues = rescale ? decomposition.values.map(restoreSquare) : [...decomposition.values];
  const x = rescale ? centered.x.map((row) => row.map(restoreSquare)) : centered.x;
  const ac = rescale ? acWork * magnitude : acWork;
  return { points: { rows: parsed.labels, cols: null, values: points }, eig: eigenvalues,
    x: options.xRet ? { rows: null, cols: null, values: x } : null, ac,
    GOF: [absSum === 0 ? NaN : retained / absSum, positiveSum === 0 ? NaN : retained / positiveSum], warnings };
}
